from lib import *
S = SS('c77')
steps = [
    step("docker context ls 有两个上下文:default(端点 unix:///var/run/docker.sock,不是当前)和 desktop-linux(端点 unix://~/.docker/run/docker.sock,当前=true)。~/.docker/config.json 里的 currentContext = desktop-linux。上下文存放在 ~/.docker/contexts/meta/名字的 sha256 目录下的 meta.json:desktop-linux 对应的目录存在,meta.json 有 Endpoints、Metadata、Name 三个键。", t=tl(S(1)), done=lidx(S(1), 'desktop-linux 当前=true', 'currentContext'), mark=lidx(S(1), 'meta.json 的键'), kv=KV([['当前上下文', 'desktop-linux(来自 config.json 的 currentContext)'], ['存放位置', '~/.docker/contexts/meta/<sha256(名字)>/meta.json']], ['当前上下文'])),
    step("新建上下文 bwlab-c77(host=unix://~/.docker/run/docker.sock),退出码 0,~/.docker/contexts/meta 下多了一个以名字 sha256 命名的目录,meta.json 里有 Name、Metadata.Description、Endpoints.docker.Host。不执行 docker context use,只用 docker --context bwlab-c77 version 或 DOCKER_CONTEXT=bwlab-c77 docker version,都得到服务端版本 29.8.2;docker context ls 里“当前”仍然是 desktop-linux。", t=tl(S(2)), done=lidx(S(2), 'docker --context bwlab-c77 version', 'DOCKER_CONTEXT=bwlab-c77'), mark=lidx(S(2), '新增了目录', 'docker context ls 里'), kv=KV([['docker context create', '写一个 meta.json,不改当前上下文'], ['--context / DOCKER_CONTEXT', '只对这条命令生效']], ['--context / DOCKER_CONTEXT'])),
    step("优先级(DOCKER_HOST 故意设成不存在的 socket):只有 DOCKER_HOST → 退出码 1,failed to connect to the docker API;DOCKER_HOST 无效但加 --context bwlab-c77 → 成功(29.8.2),--context 胜过 DOCKER_HOST;DOCKER_HOST 无效同时 DOCKER_CONTEXT=bwlab-c77 → 失败,DOCKER_HOST 胜过 DOCKER_CONTEXT;-H 指向正确 socket 并且 DOCKER_HOST 无效 → 成功,-H 胜过 DOCKER_HOST;同时给 --context 和 -H → 退出码 1,conflicting options: cannot specify both --host and --context。", t=tl(S(3)), done=lidx(S(3), '同时 --context bwlab-c77', '-H 指向正确 socket'), mark=lidx(S(3), 'DOCKER_HOST 指向不存在', 'DOCKER_CONTEXT=bwlab-c77', '同时给 --context 和 -H'), kv=KV([['-H / --context', '胜过 DOCKER_HOST'], ['DOCKER_HOST', '胜过 DOCKER_CONTEXT'], ['--context + -H', '冲突,报错']], ['DOCKER_HOST'])),
    step("ssh 上下文:docker context create … --docker host=ssh://deploy@example.invalid:2222 只创建不连接,退出码 0,Endpoints.docker = {Host: ssh://deploy@example.invalid:2222, SkipTLSVerify: false}。真正使用时:退出码 1,CLI 报 error during connect,命令是 ssh -l deploy -p 2222 -o ConnectTimeout=30 -T -- … ——ssh 上下文就是让 CLI 通过 ssh 去连对端的 Docker。", t=tl(S(4)), done=lidx(S(4), 'Endpoints.docker', 'docker context create … host=ssh'), mark=lidx(S(4), '使用这个 ssh 上下文'), kv=KV([['创建', '只写 meta.json,不连接'], ['使用', '用 ssh 运行远端的 docker 命令连接']], ['使用'])),
    step("清理:docker context rm 之后只剩 default 和 desktop-linux;~/.docker/config.json 的哈希前后相同,currentContext 仍是 desktop-linux,contexts/meta 下只剩 1 个目录。整个实验没有改动 CLI 的当前配置。", t=tl(S(5)), done=lidx(S(5), 'config.json 的哈希'), mark=lidx(S(5), '删除后 docker context ls'), kv=KV([['config.json', '哈希不变'], ['currentContext', '仍是 desktop-linux']], ['config.json'])),
]
A = mkartc('c77', 77, 'Docker,docker context,DOCKER_HOST,多环境,ssh上下文,真实验证,动画演示',
    '实测 docker context:上下文存放在 ~/.docker/contexts/meta/名字的 sha256 目录下的 meta.json,当前上下文记在 config.json 的 currentContext;新建上下文后用 --context 或 DOCKER_CONTEXT 临时使用而不改当前配置;优先级是 -H / --context 胜过 DOCKER_HOST,DOCKER_HOST 胜过 DOCKER_CONTEXT,--context 与 -H 同时给报冲突;ssh 上下文通过 ssh 连接远端。',
    '同时管几个 Docker 环境时,docker context 怎么用?它存在哪里、和 DOCKER_HOST、-H 谁的优先级高?这篇全程不执行 docker context use,用 --context 和环境变量临时切换,并验证没有改动用户的 CLI 配置。',
    [('--context 胜过 DOCKER_HOST', 'DOCKER_HOST 设成无效 socket 时,加 --context bwlab-c77 仍然成功'), ('conflicting options', '同时给 --context 和 -H 的错误'), ('哈希不变', '实验前后 ~/.docker/config.json 的 SHA-256 一致')],
    [('上下文是什么', '<p>一个上下文就是「名字 + 端点」(以及可选的 TLS 设置),存成 ~/.docker/contexts 下的一个 meta.json;当前用哪个由 ~/.docker/config.json 的 <code>currentContext</code> 决定。Docker Desktop 自带 default 和 desktop-linux。</p>'),
     ('临时使用', '<p><code>docker --context 名字 …</code> 或环境变量 <code>DOCKER_CONTEXT</code> 只影响这一条命令;<code>docker context use</code> 才会改 config.json。我这里没有执行 use,以免改动当前环境。</p>'),
     ('优先级', '<p>实测:<code>-H</code> 与 <code>--context</code> 胜过 <code>DOCKER_HOST</code>,<code>DOCKER_HOST</code> 又胜过 <code>DOCKER_CONTEXT</code>;--context 与 -H 不能同时用。所以环境里残留的 DOCKER_HOST 会悄悄压过你设的 DOCKER_CONTEXT。</p>'),
     ('ssh 上下文', '<p><code>host=ssh://用户@主机</code> 的上下文让本机 CLI 通过 ssh 连接远端的 docker(报错里能看到它调用了 ssh 命令,具体在远端执行什么,我没有看全)。我只创建了一个指向不存在主机的上下文验证了错误信息,没有连接真实的远端。</p>'),
     ('清理', '<p>context rm 删除,config.json 不变。</p>')],
    steps,
    [ENV_C + '。docker CLI 与 Docker Desktop;创建的上下文 bwlab-c77、bwlab-c77-ssh 已删除;从未执行 docker context use;实验前后比较了 ~/.docker/config.json 的 SHA-256;ssh 上下文指向保留域名 example.invalid,没有连接任何真实主机',
     '没有验证:带 TLS 的 tcp 上下文、docker context export / import、Kubernetes 上下文、DOCKER_CONFIG 指向别的配置目录、docker buildx 的构建器与上下文的关系'],
    'docker context')
